spec.section:
# session-bond.schema.json

Generated, complete JSON Schema reference. Required/default/conditional rules are not inferred.

```json
{
  "$id": "https://coding-hermes.local/chd32/schemas/session-bond.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "allOf": [
    {
      "if": {
        "properties": {
          "provisioning": {
            "const": "fork"
          }
        }
      },
      "then": {
        "required": [
          "parent_bond_id",
          "fork_point_seq",
          "fork_mode"
        ]
      }
    },
    {
      "if": {
        "properties": {
          "provisioning": {
            "const": "replace"
          }
        }
      },
      "then": {
        "required": [
          "generation"
        ]
      }
    },
    {
      "if": {
        "properties": {
          "delivery": {
            "const": "REUSE"
          }
        }
      },
      "then": {
        "properties": {
          "hermes_session_id": {
            "type": "string"
          }
        }
      }
    }
  ],
  "description": "The durable join between one agent, one room subthread/work item, one bond generation and one native Hermes session.",
  "examples": [
    {
      "agent_id": "sup-nova",
      "allocation_id": "alloc-101",
      "bond_id": "b-20261109-0914-q4x7",
      "created_at": "2026-11-09T09:14:00Z",
      "credential_scope": "profile:sup-nova/credential:cred-sup-nova-1",
      "delivery": "NEW",
      "fork_mode": "preserve_parent_snapshot",
      "fork_point_seq": 41,
      "generation": 1,
      "hermes_base_url": "https://hermes.example.test",
      "hermes_profile": "sup-nova",
      "hermes_session_id": "sess-aa11",
      "host_id": "host-main",
      "parent_bond_id": "b-20261109-0900-mgr1",
      "policy_owner": "pr-mgr-dana",
      "policy_rev": 7,
      "policy_snapshot_id": "sp-20261109-0914-p1",
      "principal_id": "pr-sup-nova",
      "profile_id": "pf-sup-nova",
      "provisioning": "fork",
      "room_id": "task-auth-14",
      "schema_version": 1,
      "session_key": "bond-b-20261109-0914-q4x7",
      "state": "active",
      "subthread_root": 42,
      "work_uid": "T-101"
    }
  ],
  "properties": {
    "agent_id": {
      "pattern": "^[a-z][a-z0-9-]*$",
      "type": "string"
    },
    "allocation_id": {
      "pattern": "^alloc-[a-z0-9][a-z0-9-]*$",
      "type": "string"
    },
    "bond_id": {
      "pattern": "^b-[0-9]{8}-[0-9]{4}-[a-z0-9-]+$",
      "type": "string"
    },
    "chat_endpoint": {
      "enum": [
        "/v1/chat/completions",
        "/api/sessions/{id}/chat",
        null
      ],
      "type": [
        "string",
        "null"
      ]
    },
    "created_at": {
      "format": "date-time",
      "type": "string"
    },
    "credential_scope": {
      "pattern": "^profile:[^/]+/credential:[^/]+$",
      "type": "string"
    },
    "delivery": {
      "enum": [
        "NEW",
        "REUSE"
      ]
    },
    "fork_mode": {
      "enum": [
        "preserve_parent_snapshot",
        "current_policy",
        null
      ],
      "type": [
        "string",
        "null"
      ]
    },
    "fork_point_seq": {
      "minimum": 1,
      "type": [
        "integer",
        "null"
      ]
    },
    "generation": {
      "minimum": 1,
      "type": "integer"
    },
    "hermes_base_url": {
      "format": "uri",
      "type": "string"
    },
    "hermes_profile": {
      "minLength": 1,
      "not": {
        "const": "default"
      },
      "type": "string"
    },
    "hermes_session_id": {
      "minLength": 1,
      "type": "string"
    },
    "host_id": {
      "pattern": "^host-[a-z0-9-]+$",
      "type": "string"
    },
    "parent_bond_id": {
      "pattern": "^b-[0-9]{8}-[0-9]{4}-[a-z0-9-]+$",
      "type": [
        "string",
        "null"
      ]
    },
    "policy_owner": {
      "pattern": "^pr-[a-z0-9-]+$",
      "type": "string"
    },
    "policy_rev": {
      "minimum": 1,
      "type": [
        "integer",
        "null"
      ]
    },
    "policy_snapshot_id": {
      "type": [
        "string",
        "null"
      ]
    },
    "principal_id": {
      "pattern": "^pr-[a-z0-9-]+$",
      "type": "string"
    },
    "profile_id": {
      "not": {
        "const": "default"
      },
      "pattern": "^pf-[a-z0-9-]+$",
      "type": "string"
    },
    "provisioning": {
      "enum": [
        "create",
        "fork",
        "replace"
      ]
    },
    "retired_at": {
      "format": "date-time",
      "type": [
        "string",
        "null"
      ]
    },
    "room_id": {
      "pattern": "^(obj|task|space)-[a-z0-9][a-z0-9-]*$",
      "type": "string"
    },
    "runtime_capabilities_digest": {
      "pattern": "^sha256:[0-9a-f]{64}$",
      "type": [
        "string",
        "null"
      ]
    },
    "schema_version": {
      "const": 1
    },
    "session_key": {
      "maxLength": 256,
      "pattern": "^[^\\r\\n\\u0000]*$",
      "type": [
        "string",
        "null"
      ]
    },
    "state": {
      "enum": [
        "provisioned",
        "active",
        "retired",
        "lost"
      ]
    },
    "subthread_root": {
      "minimum": 1,
      "type": [
        "integer",
        "null"
      ]
    },
    "work_uid": {
      "minLength": 1,
      "type": [
        "string",
        "null"
      ]
    }
  },
  "required": [
    "schema_version",
    "bond_id",
    "principal_id",
    "agent_id",
    "profile_id",
    "host_id",
    "room_id",
    "subthread_root",
    "work_uid",
    "generation",
    "parent_bond_id",
    "provisioning",
    "delivery",
    "allocation_id",
    "hermes_base_url",
    "hermes_profile",
    "credential_scope",
    "hermes_session_id",
    "session_key",
    "policy_owner",
    "state",
    "created_at"
  ],
  "title": "CHD SessionBond",
  "type": "object"
}
```
